"""Different compositions for three finger-friendly tiers; no decorative difficulty variants."""
def path(d, fill='#fff'): return f'<path d="{d}" fill="{fill}"/>'
def line(d): return path(d, 'none')
def ellipse(x,y,rx,ry): return f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="{ry}"/>'
def circle(x,y,r): return ellipse(x,y,r,r)
def rect(x,y,w,h,r=16): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}"/>'
def eye(x,y,r=10): return f'<circle cx="{x}" cy="{y}" r="{r}" fill="#000" stroke="none"/>'
def cloud(x,y): return path(f'M{x} {y} q-35 -45 5 -75 q35 -35 70 0 q40 -15 55 25 q55 0 55 50Z')
def sun(x,y): return circle(x,y,48)
def tree(x,y): return rect(x-18,y+95,36,85,4)+path(f'M{x-90} {y+110} Q{x-125} {y+25} {x-55} {y} Q{x} {y-85} {x+55} {y} Q{x+125} {y+25} {x+90} {y+110}Z')
def flower(x,y): return path(f'M{x-27} {y-27} C{x-65} {y-100} {x+65} {y-100} {x+27} {y-27} C{x+100} {y-65} {x+100} {y+65} {x+27} {y+27} C{x+65} {y+100} {x-65} {y+100} {x-27} {y+27} C{x-100} {y+65} {x-100} {y-65} {x-27} {y-27}Z')+circle(x,y,26)
def pot(x,y): return path(f'M{x-65} {y} H{x+65} L{x+45} {y+90} H{x-45}Z')+line(f'M{x} {y} V{y-65}')+ellipse(x-30,y-55,32,20)+ellipse(x+30,y-85,32,20)
def house(x,y,w=300,h=260): return rect(x,y,w,h,5)+path(f'M{x-30} {y} L{x+w/2} {y-150} L{x+w+30} {y}Z')+rect(x+w*.38,y+h*.5,w*.24,h*.5,7)+rect(x+w*.1,y+h*.2,w*.22,h*.25,6)+rect(x+w*.68,y+h*.2,w*.22,h*.25,6)
def wave(y): return line(f'M75 {y} Q150 {y-45} 225 {y} T375 {y} T525 {y} T675 {y} T825 {y} T950 {y}')
